  -- 01. Betabloqueadores y otros antihipertensivos (alfabloqueadores, acción central, vasodilatadores, ARM en HTA resistente)
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El betabloqueador que no era para la presión","texto":"Un paciente con hipertensión sin otra enfermedad recibe propranolol como primera línea y presenta fatiga y bradicardia. Los betabloqueadores no son de primera línea en la hipertensión no complicada; su lugar depende de la indicación específica."},"objetivos":["Ubicar los betabloqueadores en la HTA.","Reconocer los fármacos de segunda línea.","Aplicar la espironolactona en HTA resistente.","Revisar efectos adversos y precauciones."],"conceptos":[{"icono":"Activity","termino":"Betabloqueador","definicion":"Reduce frecuencia y contractilidad."},{"icono":"Target","termino":"Indicación","definicion":"Angina, postinfarto, IC o frecuencia."},{"icono":"Layers","termino":"Cuarta línea","definicion":"Espironolactona en HTA resistente."},{"icono":"AlertTriangle","termino":"Rebote","definicion":"Suspensión brusca de clonidina o beta."}],"secciones":[{"titulo":"Betabloqueadores","parrafos":["Los betabloqueadores reducen la frecuencia cardíaca y la contractilidad. No son de primera línea en la hipertensión no complicada, pero tienen indicaciones preferentes: angina, postinfarto, insuficiencia cardíaca con fracción de eyección reducida, control de la frecuencia en fibrilación auricular y algunas situaciones del embarazo con labetalol.","Los cardioselectivos como bisoprolol y metoprolol tienen menos efectos bronquiales; carvedilol y labetalol bloquean también alfa-1. Se evitan en asma grave, bradicardia y bloqueo auriculoventricular avanzado. Pueden enmascarar la hipoglucemia y causar fatiga o disfunción eréctil."]},{"titulo":"Alfabloqueadores y acción central","parrafos":["La doxazosina y la prazosina bloquean alfa-1 y se usan en hipertensión resistente o con hiperplasia prostática. Producen hipotensión ortostática, sobre todo en la primera dosis. No son de primera línea porque no mejoran los resultados cardiovasculares frente a otros grupos.","La clonidina y la metildopa estimulan receptores alfa-2 centrales. La metildopa se usa en el embarazo; la clonidina puede causar sedación, boca seca e hipertensión de rebote si se suspende bruscamente. La educación sobre la retirada gradual es esencial."]},{"titulo":"Vasodilatadores y HTA resistente","parrafos":["La hidralazina y el minoxidil son vasodilatadores directos. La hidralazina puede causar lupus-like y se combina con nitratos en la insuficiencia cardíaca de pacientes afrodescendientes. El minoxidil produce hirsutismo y retención de líquidos.","En la hipertensión resistente, la espironolactona es la cuarta línea con mayor evidencia. Se inicia con 25 mg y se controla potasio y creatinina. La ginecomastia puede limitar la adherencia; la eplerenona es una alternativa. El QF revisa duplicidades, adherencia y causas de pseudorresistencia."]}],"errores":[{"error":"Usar beta como primera línea general.","correccion":"Requiere indicación específica."},{"error":"Suspender clonidina bruscamente.","correccion":"Produce rebote."},{"error":"No controlar potasio con espironolactona.","correccion":"Riesgo de hiperpotasemia."}],"comprueba":[{"pregunta":"¿Cuándo se prefiere un betabloqueador?","respuesta":"Angina, postinfarto, IC o frecuencia."},{"pregunta":"¿Qué efecto tiene la doxazosina?","respuesta":"Hipotensión ortostática."},{"pregunta":"¿Qué cuarta línea se usa en HTA resistente?","respuesta":"Espironolactona."}],"resumen":["Los beta no son primera línea general.","Las indicaciones específicas definen su uso.","La espironolactona es la cuarta línea de elección.","La retirada brusca causa rebote."],"referencias":[{"cita":"European Society of Cardiology. 2024 ESC Guidelines for the management of elevated blood pressure and hypertension. Eur Heart J. 2024.","url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/elevated-blood-pressure-and-hypertension/"},{"cita":"Ministerio de Salud y Protección Social. Actualización parcial de la GPC de hipertensión arterial primaria (Guía n.º 18, 2.ª ed.). Bogotá; 2025.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/CA/gpc-actualizacion-parcial-hta-primaria-vps.pdf"}],"imagenes":[{"ubicacion":"Otros antihipertensivos","descripcion":"Indicaciones de betabloqueadores y fármacos de cuarta línea.","alt":"Betabloqueadores y otros antihipertensivos"}],"keywords":["betabloqueadores hta","espironolactona hta resistente","alfabloqueadores","clonidina"],"mapa":{"centro":"Otros antihipertensivos","ramas":[{"titulo":"Beta","icono":"Activity","nodos":["Bisoprolol","Carvedilol","Indicaciones"]},{"titulo":"Alfa","icono":"Gauge","nodos":["Doxazosina","Próstata","Ortostatismo"]},{"titulo":"Centrales","icono":"Network","nodos":["Clonidina","Metildopa","Rebote"]},{"titulo":"Resistente","icono":"Layers","nodos":["Espironolactona","Potasio","Control"]}]},"proceso":{"titulo":"Revisión del esquema","intro":"","pasos":[{"titulo":"Indicación","detalle":"¿Por qué beta o alfa?","icono":"Target","evidencia":"Diagnóstico."},{"titulo":"Riesgos","detalle":"Asma, bradicardia y ortostatismo.","icono":"AlertTriangle","evidencia":"Revisión."},{"titulo":"Resistencia","detalle":"Adherencia y causas.","icono":"Search","evidencia":"Evaluación."},{"titulo":"Cuarta línea","detalle":"Espironolactona y potasio.","icono":"Layers","evidencia":"Fórmula."},{"titulo":"Educar","detalle":"Retirada gradual.","icono":"Users","evidencia":"Consejería."}]},"caso":{"titulo":"HTA resistente","contexto":"Paciente con tres fármacos a dosis óptimas y presión aún elevada, sin causas secundarias.","pregunta":"¿Qué cuarta línea se considera?","opciones":[{"texto":"Espironolactona.","correcta":true,"retro":"Es la opción con mayor evidencia."},{"texto":"Otro betabloqueador.","correcta":false,"retro":"No es la cuarta línea."},{"texto":"Duplicar la tiazida.","correcta":false,"retro":"Puede empeorar los electrolitos."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Betabloqueadores y otros antihipertensivos (alfabloqueadores, acción central, vasodilatadores, ARM en HTA resistente)$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Betabloqueadores y otros antihipertensivos (alfabloqueadores, acción central, vasodilatadores, ARM en HTA resistente)$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
