  -- 02. GPC de HTA: MinSalud 2025, ESH 2023, ESC 2024 y AHA/ACC 2025
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Cuatro guías, una decisión","texto":"Una guía prioriza la combinación inicial; otra discute el umbral en adultos mayores. El clínico necesita criterio para integrar las recomendaciones. Conocer las diferencias evita aplicar una regla sin contexto."},"objetivos":["Comparar umbrales y metas.","Aplicar la lógica de la combinación inicial.","Reconocer el enfoque de riesgo.","Traducir las guías a la práctica colombiana."],"conceptos":[{"icono":"BookOpen","termino":"GPC","definicion":"Guía de práctica clínica colombiana."},{"icono":"Target","termino":"Meta","definicion":"Objetivo de presión individualizado."},{"icono":"Layers","termino":"Combinación","definicion":"Dos fármacos en una tableta."},{"icono":"Users","termino":"Individualización","definicion":"Ajustar al riesgo y tolerancia."}],"secciones":[{"titulo":"Umbrales y metas","parrafos":["La guía colombiana actualizada en 2025, la ESH 2023, la ESC 2024 y la AHA/ACC 2025 comparten la importancia de medir bien la presión, estratificar el riesgo y tratar con combinaciones cuando el riesgo es alto. Difieren en los umbrales y en las metas, especialmente en adultos mayores y en prevención primaria.","La ESC 2024 propone una meta de presión sistólica de 120-129 mmHg en la mayoría de adultos tratados si se tolera, con individualización. La AHA/ACC 2025 mantiene la definición de hipertensión desde 130/80 mmHg y una meta menor de 130/80. La guía colombiana adapta estas recomendaciones al contexto local y al PBS."]},{"titulo":"Inicio del tratamiento","parrafos":["En la mayoría de pacientes con hipertensión confirmada y riesgo elevado, las guías recomiendan iniciar con una combinación de dos fármacos, preferiblemente en una sola tableta. Los grupos de elección son IECA o ARA-II con calcioantagonista o tiazida. La monoterapia se reserva para hipertensión leve y bajo riesgo.","El estilo de vida acompaña siempre al tratamiento: reducción de sal, dieta saludable, actividad física, control del peso, moderación del alcohol y cesación tabáquica. La combinación inicial mejora el control y la adherencia."]},{"titulo":"Aplicación en Colombia","parrafos":["El QF traduce las guías a la disponibilidad del PBS, a las combinaciones cubiertas y a las barreras de acceso. También revisa la coherencia entre la guía y la fórmula, y propone ajustes documentados cuando hay discrepancias.","Las guías no sustituyen el juicio clínico. El paciente frágil, el adulto mayor con ortostatismo o la persona con enfermedad renal requieren metas y fármacos individualizados. La evidencia orienta; la decisión se comparte."]}],"errores":[{"error":"Aplicar una meta única a todos.","correccion":"La individualización es clave."},{"error":"Iniciar monoterapia en alto riesgo.","correccion":"Se prefiere combinación."},{"error":"Ignorar la cobertura del PBS.","correccion":"Condiciona la adherencia."}],"comprueba":[{"pregunta":"¿Qué guía colombiana se actualizó en 2025?","respuesta":"La GPC de HTA primaria."},{"pregunta":"¿Qué combinación se prefiere al inicio?","respuesta":"IECA/ARA-II con calcioantagonista o tiazida."},{"pregunta":"¿Qué se individualiza?","respuesta":"La meta y la elección."}],"resumen":["Las guías comparten principios y difieren en matices.","La combinación inicial es la norma en alto riesgo.","El contexto colombiano condiciona el acceso.","La meta se individualiza."],"referencias":[{"cita":"Ministerio de Salud y Protección Social. Actualización parcial de la GPC de hipertensión arterial primaria (Guía n.º 18, 2.ª ed.). Bogotá; 2025.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/CA/gpc-actualizacion-parcial-hta-primaria-vps.pdf"},{"cita":"European Society of Cardiology. 2024 ESC Guidelines for the management of elevated blood pressure and hypertension. Eur Heart J. 2024.","url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/elevated-blood-pressure-and-hypertension/"},{"cita":"American Heart Association/American College of Cardiology. 2025 High Blood Pressure Guideline. J Am Coll Cardiol. 2025.","url":"https://www.jacc.org/doi/10.1016/j.jacc.2025.05.007"}],"imagenes":[{"ubicacion":"Guías","descripcion":"Comparación de umbrales, metas y combinaciones.","alt":"Guías de hipertensión arterial 2025"}],"keywords":["gpc hta 2025","esc 2024 hta","aha acc 2025","metas presión arterial"],"mapa":{"centro":"Guías de HTA","ramas":[{"titulo":"Colombia","icono":"Landmark","nodos":["MinSalud 2025","PBS","Riesgo"]},{"titulo":"Europa","icono":"Globe","nodos":["ESH 2023","ESC 2024"]},{"titulo":"EE. UU.","icono":"Globe","nodos":["AHA/ACC 2025","Prevención"]},{"titulo":"Práctica","icono":"Target","nodos":["Umbral","Meta","Combinación"]}]},"proceso":{"titulo":"Aplicar la guía","intro":"","pasos":[{"titulo":"Confirmar","detalle":"Diagnóstico y medición.","icono":"Gauge","evidencia":"Registro."},{"titulo":"Estratificar","detalle":"Riesgo y comorbilidad.","icono":"LineChart","evidencia":"Evaluación."},{"titulo":"Definir","detalle":"Meta individualizada.","icono":"Target","evidencia":"Plan."},{"titulo":"Elegir","detalle":"Combinación inicial.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Seguir","detalle":"Control y tolerancia.","icono":"CalendarClock","evidencia":"Consulta."}]},"caso":{"titulo":"HTA de alto riesgo","contexto":"Paciente con hipertensión, diabetes y albuminuria, sin tratamiento previo.","pregunta":"¿Qué inicio es coherente con las guías?","opciones":[{"texto":"Monoterapia con un diurético.","correcta":false,"retro":"El alto riesgo prefiere combinación."},{"texto":"IECA o ARA-II más calcioantagonista o tiazida.","correcta":true,"retro":"Combinación inicial preferida."},{"texto":"Solo cambios de estilo de vida.","correcta":false,"retro":"El riesgo exige fármacos."}]}}$j$::jsonb;
