  -- 03. Caso: HTA no controlada, politerapia fija y adherencia
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Tres tabletas que podían ser una","texto":"Un paciente toma amlodipino, losartán y una tiazida por separado, olvida una dosis y no alcanza la meta. La combinación a dosis fija puede simplificar el esquema y mejorar el control sin cambiar los principios farmacológicos."},"objetivos":["Analizar la falta de control.","Aplicar la combinación a dosis fija.","Diseñar un plan de adherencia.","Documentar el seguimiento."],"conceptos":[{"icono":"Layers","termino":"Politerapia fija","definicion":"Dos o tres fármacos en una tableta."},{"icono":"Users","termino":"Adherencia","definicion":"Barreras y simplificación."},{"icono":"Gauge","termino":"Control","definicion":"Meta individualizada de presión."},{"icono":"FileCheck","termino":"Seguimiento","definicion":"Medir y ajustar."}],"secciones":[{"titulo":"Análisis","parrafos":["Ante una hipertensión no controlada se revisan adherencia, técnica de medición, efectos adversos y coherencia del esquema. El paciente del caso toma tres fármacos de primera línea, pero olvida la dosis de la noche y no lleva registro de casa.","La combinación de los tres grupos es racional, pero la carga de tabletas es alta. La simplificación con una combinación a dosis fija puede reducir olvidos y mejorar la persistencia."]},{"titulo":"Intervención","parrafos":["El QF propone al prescriptor una combinación fija disponible y cubierta, verifica la equivalencia de dosis y explica el cambio. También revisa el horario, la técnica de automedición y las barreras económicas.","Se acuerda un plan con registro de presión en casa, control en cuatro semanas y educación sobre los efectos adversos. La meta se individualiza según el riesgo y la tolerancia."]},{"titulo":"Seguimiento","parrafos":["En el control se revisan presión, adherencia, efectos adversos y electrolitos si hay tiazida. Si la presión sigue alta, se confirma la adherencia y se descartan causas secundarias antes de escalar.","El caso muestra que la politerapia fija no es un simple cambio de presentación: es una intervención de adherencia que debe acompañarse de educación y seguimiento. Si el paciente presenta mareo o hipotensión, se revisa el horario y la dosis antes de suspender; la combinación fija no debe retirarse sin valoración."]}],"errores":[{"error":"Escalar sin revisar adherencia.","correccion":"Es la causa más frecuente."},{"error":"Cambiar sin verificar equivalencias.","correccion":"Puede alterar el control."},{"error":"No educar sobre el nuevo esquema.","correccion":"La confusión reduce la adherencia."}],"comprueba":[{"pregunta":"¿Qué ventaja tiene la combinación fija?","respuesta":"Menos tabletas y mejor adherencia."},{"pregunta":"¿Qué se revisa antes de escalar?","respuesta":"Adherencia y técnica de medición."},{"pregunta":"¿Cuándo se controla?","respuesta":"En cuatro semanas."}],"resumen":["La falta de control exige análisis, no solo escalar.","La combinación fija simplifica el esquema.","La educación acompaña el cambio.","El seguimiento confirma el efecto."],"referencias":[{"cita":"Ministerio de Salud y Protección Social. Actualización parcial de la GPC de hipertensión arterial primaria (Guía n.º 18, 2.ª ed.). Bogotá; 2025.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/CA/gpc-actualizacion-parcial-hta-primaria-vps.pdf"}],"imagenes":[{"ubicacion":"Caso","descripcion":"Esquema antes y después de la combinación fija.","alt":"Caso de HTA no controlada y politerapia fija"}],"keywords":["hta no controlada","combinación dosis fija","adherencia hta","politerapia"],"mapa":{"centro":"HTA no controlada","ramas":[{"titulo":"Evaluar","icono":"Gauge","nodos":["PA","Adherencia","Técnica"]},{"titulo":"Simplificar","icono":"Layers","nodos":["A+C","A+D","Una tableta"]},{"titulo":"Barreras","icono":"AlertTriangle","nodos":["Costo","Olvido","Efectos"]},{"titulo":"Seguir","icono":"CalendarClock","nodos":["4 semanas","AMPA","Metas"]}]},"proceso":{"titulo":"Optimizar el esquema","intro":"","pasos":[{"titulo":"Medir","detalle":"PA y adherencia.","icono":"Gauge","evidencia":"Registro."},{"titulo":"Revisar","detalle":"Dosis y efectos.","icono":"ClipboardList","evidencia":"Lista."},{"titulo":"Simplificar","detalle":"Combinación fija.","icono":"Layers","evidencia":"Fórmula."},{"titulo":"Educar","detalle":"Horario y automedición.","icono":"Users","evidencia":"Consejería."},{"titulo":"Seguir","detalle":"Control y ajuste.","icono":"CalendarClock","evidencia":"Consulta."}]},"caso":{"titulo":"Tres tabletas","contexto":"Paciente adherente a medias, con amlodipino, losartán e hidroclorotiazida por separado y presión de 150/95.","pregunta":"¿Qué intervención plantea el QF?","opciones":[{"texto":"Añadir una cuarta tableta.","correcta":false,"retro":"Aumenta la carga y los olvidos."},{"texto":"Proponer una combinación a dosis fija.","correcta":true,"retro":"Simplifica y mejora la adherencia."},{"texto":"Suspender la tiazida.","correcta":false,"retro":"Perdería eficacia."}]}}$j$::jsonb;
