  -- 04. Introducción a la unidad: fisiopatología y objetivos terapéuticos en IC y angina
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"El corazón que compensa y se daña","texto":"En la insuficiencia cardíaca, la activación neurohormonal sostiene la presión a corto plazo pero remodela y deteriora el corazón a largo plazo. En la angina, el problema es el desequilibrio entre oferta y demanda de oxígeno. Entender ambos mecanismos ordena el tratamiento."},"objetivos":["Explicar la activación neurohormonal en la IC.","Comprender el desequilibrio de la angina.","Reconocer los objetivos terapéuticos.","Conectar fisiopatología y fármacos."],"conceptos":[{"icono":"Activity","termino":"Remodelado","definicion":"Cambio estructural que empeora la función."},{"icono":"Network","termino":"Neurohormonal","definicion":"SRAA y simpático activados."},{"icono":"Gauge","termino":"Oferta-demanda","definicion":"Balance de oxígeno en la angina."},{"icono":"Target","termino":"Objetivos","definicion":"Síntomas y pronóstico."}],"secciones":[{"titulo":"Insuficiencia cardíaca","parrafos":["La insuficiencia cardíaca es un síndrome con síntomas y signos de congestión o bajo gasto, causado por una alteración estructural o funcional. La activación del sistema renina-angiotensina-aldosterona y del sistema simpático compensa la caída del gasto, pero produce vasoconstricción, retención de sodio y remodelado.","El tratamiento bloquea esa activación para mejorar síntomas y pronóstico. Los cuatro pilares de la IC con fracción de eyección reducida actúan sobre el SRAA, el simpático, el receptor mineralocorticoide y el transporte renal de sodio y glucosa."]},{"titulo":"Angina","parrafos":["La angina estable refleja isquemia miocárdica por un desequilibrio entre la oferta y la demanda de oxígeno, habitualmente por aterosclerosis coronaria. El tratamiento busca reducir la demanda (frecuencia y contractilidad) o mejorar la oferta (vasodilatación coronaria) y, cuando está indicado, revascularizar.","Los betabloqueadores y los calcioantagonistas reducen la demanda; los nitratos y la ranolazina mejoran el flujo o el metabolismo. La antiagregación y las estatinas modifican el riesgo de eventos, no solo el síntoma."]},{"titulo":"Objetivos","parrafos":["En ambas condiciones, el tratamiento tiene dos metas: aliviar síntomas y mejorar el pronóstico. Los fármacos sintomáticos, como los diuréticos y los nitratos, no siempre reducen la mortalidad; los que modifican el pronóstico, como los pilares de la IC o las estatinas, son prioritarios.","El QF revisa que el paciente reciba la terapia con beneficio pronóstico, que los síntomas estén controlados y que no haya fármacos que empeoren la enfermedad. La fisiopatología explica por qué cada grupo está o no indicado."]}],"errores":[{"error":"Tratar solo el síntoma.","correccion":"El pronóstico también importa."},{"error":"No revisar fármacos que empeoran.","correccion":"AINE y glitazonas son riesgos."},{"error":"Ignorar la congestión.","correccion":"El diurético es necesario."}],"comprueba":[{"pregunta":"¿Qué sistemas se activan en la IC?","respuesta":"SRAA y simpático."},{"pregunta":"¿Qué busca el tratamiento de la angina?","respuesta":"Equilibrar oferta y demanda."},{"pregunta":"¿Cuáles son las dos metas?","respuesta":"Síntomas y pronóstico."}],"resumen":["La IC activa el SRAA y el simpático.","La angina es un desequilibrio de oxígeno.","El tratamiento busca síntomas y pronóstico.","La fisiopatología guía la elección."],"referencias":[{"cita":"European Society of Cardiology. 2026 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2026.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Heart-Failure"},{"cita":"European Society of Cardiology. 2024 ESC Guidelines for the management of chronic coronary syndromes. Eur Heart J. 2024.","url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/chronic-coronary-syndromes/"}],"imagenes":[{"ubicacion":"Unidad 3","descripcion":"Mecanismos de IC y angina con sus dianas terapéuticas.","alt":"Fisiopatología de la IC y la angina"}],"keywords":["fisiopatología insuficiencia cardíaca","angina estable","sraa","remodelado"],"mapa":{"centro":"IC y angina","ramas":[{"titulo":"IC","icono":"Activity","nodos":["SRAA","Simpático","Remodelado","Congestión"]},{"titulo":"Angina","icono":"Gauge","nodos":["Oferta","Demanda","Isquemia"]},{"titulo":"Fármacos","icono":"Pill","nodos":["Pilares","Antiaginosos","Diuréticos"]},{"titulo":"Metas","icono":"Target","nodos":["Síntomas","Mortalidad","Calidad"]}]},"proceso":{"titulo":"Del mecanismo al fármaco","intro":"","pasos":[{"titulo":"Identificar","detalle":"IC o angina.","icono":"Search","evidencia":"Diagnóstico."},{"titulo":"Explicar","detalle":"Mecanismo dominante.","icono":"BookOpen","evidencia":"Notas."},{"titulo":"Elegir","detalle":"Fármaco con beneficio.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Aliviar","detalle":"Síntomas con seguridad.","icono":"Activity","evidencia":"Control."},{"titulo":"Revisar","detalle":"Fármacos que empeoran.","icono":"AlertTriangle","evidencia":"Lista."}]},"caso":{"titulo":"Congestión y bajo gasto","contexto":"Paciente con disnea, edema y fatiga; FEVI reducida.","pregunta":"¿Qué mecanismo explica el tratamiento?","opciones":[{"texto":"La activación neurohormonal.","correcta":true,"retro":"Los pilares bloquean esa activación."},{"texto":"Solo la retención de líquidos.","correcta":false,"retro":"El diurético alivia, pero no es todo."},{"texto":"La inflamación aguda.","correcta":false,"retro":"No es el mecanismo central."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción a la unidad: fisiopatología y objetivos terapéuticos en IC y angina$t$ AND deleted_at IS NULL
