  -- 05. Los cuatro pilares de la ICFEr: ARNI/IECA, betabloqueador, ARM e iSGLT2
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Cuatro fármacos que cambian el pronóstico","texto":"Un paciente con FEVI de 30 % recibe solo un diurético. Aliviar la congestión no es suficiente: los cuatro pilares reducen mortalidad y hospitalización. Iniciarlos temprano y titularlos es la prioridad."},"objetivos":["Explicar el beneficio de cada pilar.","Aplicar inicio y titulación.","Monitorizar presión, potasio y renal.","Reconocer su lugar en FEVIlR y FEVIp."],"conceptos":[{"icono":"Layers","termino":"Cuatro pilares","definicion":"ARNI/IECA, beta, ARM e iSGLT2."},{"icono":"Target","termino":"Dosis objetivo","definicion":"La máxima tolerada."},{"icono":"TestTube","termino":"Potasio","definicion":"Riesgo con ARM y SRAA."},{"icono":"Activity","termino":"FEVIr","definicion":"Fracción de eyección reducida."}],"secciones":[{"titulo":"Los cuatro pilares","parrafos":["En la insuficiencia cardíaca con fracción de eyección reducida, cuatro grupos reducen mortalidad y hospitalización: el ARNI o, si no es posible, un IECA o ARA-II; un betabloqueador con evidencia (bisoprolol, carvedilol, metoprolol succinato o nebivolol); un antagonista del receptor mineralocorticoide (espironolactona o eplerenona); y un inhibidor de SGLT2 (dapagliflozina o empagliflozina).","El ARNI demostró superioridad frente a enalapril. Los betabloqueadores con evidencia reducen la mortalidad. Los ARM reducen mortalidad y hospitalización, con vigilancia del potasio. Los iSGLT2 reducen hospitalización y muerte cardiovascular, con beneficio independiente de la diabetes."]},{"titulo":"Inicio y titulación","parrafos":["La recomendación actual es iniciar los cuatro grupos de forma temprana, no esperar meses entre uno y otro, y titular hasta la dosis objetivo o la máxima tolerada. En pacientes frágiles o hipotensos se puede escalonar, pero la meta sigue siendo completar el esquema.","Las dosis de referencia incluyen sacubitrilo/valsartán 24/26 mg cada 12 horas hasta 97/103 mg; bisoprolol 1,25 mg hasta 10 mg al día; carvedilol 3,125 mg cada 12 horas hasta 25 mg cada 12 horas; espironolactona 25 mg hasta 50 mg; dapagliflozina 10 mg y empagliflozina 10 mg al día."]},{"titulo":"Monitorización","parrafos":["Se controlan presión, frecuencia, potasio, creatinina y síntomas después de cada inicio o ajuste. La caída leve de la función renal puede ser esperada; un deterioro significativo o una hiperpotasemia exigen revisión. La educación incluye peso diario, signos de alarma y adherencia.","En la FEVI levemente reducida y preservada, el iSGLT2 tiene beneficio; el ARNI y los ARM se consideran según el fenotipo. El QF revisa que el paciente con FEVI reducida reciba los cuatro pilares y que no haya fármacos que los contrarresten."]}],"errores":[{"error":"Quedarse en el diurético.","correccion":"No modifica el pronóstico."},{"error":"No controlar potasio.","correccion":"ARM y SRAA lo elevan."},{"error":"Titular demasiado lento sin razón.","correccion":"Se pierde beneficio."}],"comprueba":[{"pregunta":"¿Cuáles son los cuatro pilares?","respuesta":"ARNI/IECA, beta, ARM e iSGLT2."},{"pregunta":"¿Qué se controla tras cada ajuste?","respuesta":"Presión, potasio y creatinina."},{"pregunta":"¿Qué pilar beneficia también la FEVIp?","respuesta":"El iSGLT2."}],"resumen":["Los cuatro pilares reducen mortalidad.","Se inician temprano y se titulan.","La monitorización es obligatoria.","El diurético alivia, pero no basta."],"referencias":[{"cita":"European Society of Cardiology. 2026 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2026.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Heart-Failure"},{"cita":"AEMPS-CIMA. Ficha técnica de Entresto 24 mg/26 mg comprimidos recubiertos con película.","url":"https://cima.aemps.es/cima/dochtml/ft/1151058001/FT_1151058001.html"}],"imagenes":[{"ubicacion":"Pilares","descripcion":"Los cuatro pilares de la ICFEr y sus dianas.","alt":"Cuatro pilares de la insuficiencia cardíaca"}],"keywords":["cuatro pilares ic","arni","betabloqueador ic","arm","isglt2"],"mapa":{"centro":"ICFEr","ramas":[{"titulo":"ARNI/IECA","icono":"ShieldCheck","nodos":["Sacubitrilo","Enalapril","36 h"]},{"titulo":"Beta","icono":"Activity","nodos":["Bisoprolol","Carvedilol","Metoprolol"]},{"titulo":"ARM","icono":"Droplets","nodos":["Espironolactona","Eplerenona","Potasio"]},{"titulo":"iSGLT2","icono":"Gauge","nodos":["Dapagliflozina","Empagliflozina","Renal"]}]},"proceso":{"titulo":"Implementar los pilares","intro":"","pasos":[{"titulo":"Confirmar","detalle":"FEVI y congestión.","icono":"Activity","evidencia":"Ecocardiograma."},{"titulo":"Iniciar","detalle":"Cuatro grupos temprano.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Titular","detalle":"Dosis objetivo tolerada.","icono":"LineChart","evidencia":"Esquema."},{"titulo":"Controlar","detalle":"Presión, potasio y renal.","icono":"TestTube","evidencia":"Laboratorio."},{"titulo":"Educar","detalle":"Peso y adherencia.","icono":"Users","evidencia":"Consejería."}]},"caso":{"titulo":"Solo diurético","contexto":"Paciente con FEVI de 30 % y congestión que recibe solo furosemida.","pregunta":"¿Qué falta?","opciones":[{"texto":"Nada; el diurético es suficiente.","correcta":false,"retro":"No reduce mortalidad."},{"texto":"Los cuatro pilares con titulación.","correcta":true,"retro":"Modifican el pronóstico."},{"texto":"Solo un betabloqueador.","correcta":false,"retro":"El esquema debe completarse."}]}}$j$::jsonb;
