  -- 06. Diuréticos de asa, digoxina e ivabradina
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La digoxina tiene margen estrecho","texto":"Una paciente con insuficiencia cardíaca y función renal reducida recibe digoxina y presenta náuseas y visión amarilla. La digoxina sigue siendo útil, pero exige dosis cuidadosa y monitorización."},"objetivos":["Aplicar el uso de diuréticos de asa.","Reconocer la toxicidad de la digoxina.","Indicar ivabradina con criterio.","Monitorizar y educar."],"conceptos":[{"icono":"Droplets","termino":"Asa","definicion":"Diurético potente para congestión."},{"icono":"Pill","termino":"Digoxina","definicion":"Margen terapéutico estrecho."},{"icono":"Timer","termino":"Ivabradina","definicion":"Reduce frecuencia sin bajar la presión."},{"icono":"TestTube","termino":"Nivel","definicion":"Digoxinemia 0,5-0,9 ng/mL en IC."}],"secciones":[{"titulo":"Diuréticos de asa","parrafos":["La furosemida, la torasemida y la bumetanida alivian la congestión. La dosis se individualiza según el peso, la diuresis y los síntomas. La vía intravenosa se usa en la descompensación grave. Se controlan potasio, magnesio, creatinina y presión.","La resistencia diurética se maneja aumentando la dosis, fraccionando la administración o combinando con una tiazida. El paciente debe registrar el peso y consultar si aumenta o si aparecen síntomas de hipotensión."]},{"titulo":"Digoxina","parrafos":["La digoxina reduce las hospitalizaciones en la IC y controla la frecuencia en la fibrilación auricular. Tiene un margen terapéutico estrecho y se acumula en la insuficiencia renal. La dosis habitual es 0,125-0,25 mg al día, con ajuste por edad y función renal.","La toxicidad se manifiesta con náuseas, anorexia, visión amarilla o borrosa, confusión y arritmias. El riesgo aumenta con hipopotasemia, hipomagnesemia, hipercalcemia, insuficiencia renal y fármacos que aumentan sus niveles, como amiodarona, verapamilo y claritromicina. Se monitoriza el nivel sérico cuando hay sospecha."]},{"titulo":"Ivabradina","parrafos":["La ivabradina inhibe la corriente If del nodo sinusal y reduce la frecuencia sin afectar la presión ni la contractilidad. Se indica en IC con fracción de eyección reducida, ritmo sinusal y frecuencia de 70 lpm o más pese a betabloqueador optimizado, o cuando el betabloqueador no se tolera.","Puede causar bradicardia y fenómenos visuales (fosfenos). Es sustrato del CYP3A4 y debe revisarse con inhibidores potentes. No se usa en fibrilación auricular ni en marcapasos dependientes del nodo sinusal."]}],"errores":[{"error":"No ajustar digoxina por renal.","correccion":"Se acumula y intoxica."},{"error":"Ignorar la hipopotasemia.","correccion":"Aumenta la toxicidad."},{"error":"Usar ivabradina en FA.","correccion":"No está indicada."}],"comprueba":[{"pregunta":"¿Qué controla el diurético de asa?","respuesta":"La congestión, no el pronóstico."},{"pregunta":"¿Cuál es el rango de digoxinemia en IC?","respuesta":"0,5-0,9 ng/mL."},{"pregunta":"¿Cuándo se usa ivabradina?","respuesta":"Ritmo sinusal y FC alta pese a beta."}],"resumen":["El diurético alivia la congestión.","La digoxina exige dosis y niveles.","La ivabradina reduce la frecuencia.","La monitorización evita toxicidad."],"referencias":[{"cita":"European Society of Cardiology. 2026 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2026.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Heart-Failure"},{"cita":"AEMPS-CIMA. Ficha técnica de Digoxina Kern Pharma 0,25 mg comprimidos EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/63643/FT_63643.html"}],"imagenes":[{"ubicacion":"Terapia adicional","descripcion":"Diurético, digoxina e ivabradina con sus controles.","alt":"Diuréticos, digoxina e ivabradina en IC"}],"keywords":["furosemida ic","digoxina toxicidad","ivabradina","diurético de asa"],"mapa":{"centro":"Terapia adicional","ramas":[{"titulo":"Diurético","icono":"Droplets","nodos":["Furosemida","Torasemida","Peso"]},{"titulo":"Digoxina","icono":"Pill","nodos":["Dosis","Nivel","Toxicidad"]},{"titulo":"Ivabradina","icono":"Timer","nodos":["Ritmo sinusal","FC 70","Fosfenos"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Potasio","Renal","Interacciones"]}]},"proceso":{"titulo":"Checklist adicional","intro":"","pasos":[{"titulo":"Congestión","detalle":"Diurético y peso.","icono":"Droplets","evidencia":"Registro."},{"titulo":"Digoxina","detalle":"Dosis, nivel y toxicidad.","icono":"Pill","evidencia":"Laboratorio."},{"titulo":"Ivabradina","detalle":"Ritmo y frecuencia.","icono":"Timer","evidencia":"ECG."},{"titulo":"Interacción","detalle":"CYP3A4 y renal.","icono":"Network","evidencia":"Lista."},{"titulo":"Educación","detalle":"Signos de toxicidad.","icono":"Users","evidencia":"Consejería."}]},"caso":{"titulo":"Náuseas y visión amarilla","contexto":"Paciente con digoxina, insuficiencia renal y potasio de 3,1 que presenta náuseas y visión alterada.","pregunta":"¿Qué sospecha el QF?","opciones":[{"texto":"Toxicidad por digoxina.","correcta":true,"retro":"Los síntomas y factores de riesgo coinciden."},{"texto":"Efecto normal del fármaco.","correcta":false,"retro":"No son efectos esperados."},{"texto":"Falta de adherencia.","correcta":false,"retro":"El cuadro sugiere lo contrario."}]}}$j$::jsonb;
