  -- 07. Fármacos a evitar en IC y evidencia de costo-efectividad
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El AINE que descompensó la IC","texto":"Un paciente con insuficiencia cardíaca estable inicia un AINE para el dolor y vuelve con edema y disnea. Algunos fármacos de uso común empeoran la IC. Revisarlos es una intervención de seguridad de alto impacto."},"objetivos":["Identificar fármacos que empeoran la IC.","Reconocer alternativas seguras.","Analizar la costo-efectividad.","Aplicar la revisión en la dispensación."],"conceptos":[{"icono":"AlertTriangle","termino":"AINE","definicion":"Retiene sodio y empeora la IC."},{"icono":"Pill","termino":"Glitazona","definicion":"Retiene líquidos; evitar en IC."},{"icono":"Activity","termino":"No DHP","definicion":"Verapamilo y diltiazem empeoran la FEVIr."},{"icono":"LineChart","termino":"Costo-efectividad","definicion":"Beneficio por recurso invertido."}],"secciones":[{"titulo":"Fármacos que empeoran la IC","parrafos":["Los AINE y los coxib producen retención de sodio y agua, aumentan la presión y deterioran la función renal. Las glitazonas retienen líquidos y pueden descompensar la IC. El verapamilo y el diltiazem reducen la contractilidad y se evitan en la IC con fracción de eyección reducida.","Algunos antiarrítmicos de clase I, como flecainida y propafenona, se contraindican en la cardiopatía estructural. La saxagliptina se asoció con más hospitalizaciones por IC. Los descongestionantes y los suplementos con efedra también son riesgosos."]},{"titulo":"Alternativas y revisión","parrafos":["Para el dolor se prefieren alternativas según el caso, como paracetamol a dosis seguras, medidas físicas o terapias tópicas, siempre evaluando el riesgo hepático y renal. La revisión de la medicación completa, incluida la venta libre, es parte de la dispensación.","El QF documenta el riesgo, comunica al prescriptor y propone alternativas. En la IC, la educación sobre no automedicarse con AINE es tan importante como la fórmula."]},{"titulo":"Costo-efectividad","parrafos":["Los cuatro pilares y los iSGLT2 han demostrado ser costo-efectivos en la IC porque reducen hospitalizaciones. El costo inicial puede ser alto, pero el ahorro por menos ingresos y mejor calidad de vida lo compensa. En Colombia, el acceso depende del PBS y de mecanismos como MIPRES.","El QF puede apoyar la gestión del acceso, la adherencia y la continuidad. La evidencia de costo-efectividad es un argumento para priorizar la terapia con beneficio pronóstico sobre los fármacos solo sintomáticos."]}],"errores":[{"error":"No preguntar por venta libre.","correccion":"Es la fuente más frecuente."},{"error":"Usar no DHP en FEVIr.","correccion":"Empeoran la contractilidad."},{"error":"Ignorar el costo del abandono.","correccion":"La hospitalización cuesta más."}],"comprueba":[{"pregunta":"¿Qué fármacos empeoran la IC?","respuesta":"AINE, glitazonas y no DHP."},{"pregunta":"¿Qué alternativa analgésica se valora?","respuesta":"Paracetamol con precaución."},{"pregunta":"¿Por qué son costo-efectivos los pilares?","respuesta":"Reducen hospitalizaciones."}],"resumen":["Los AINE y otros fármacos descompensan la IC.","La revisión incluye la venta libre.","La alternativa debe ser segura.","La costo-efectividad apoya los pilares."],"referencias":[{"cita":"European Society of Cardiology. 2026 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2026.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Heart-Failure"}],"imagenes":[{"ubicacion":"Seguridad","descripcion":"Lista de fármacos a evitar en insuficiencia cardíaca.","alt":"Fármacos a evitar en insuficiencia cardíaca"}],"keywords":["fármacos a evitar ic","aine insuficiencia cardíaca","glitazonas","costo-efectividad ic"],"mapa":{"centro":"Fármacos a evitar","ramas":[{"titulo":"Analgésicos","icono":"AlertTriangle","nodos":["AINE","Coxib","Alternativas"]},{"titulo":"Cardíacos","icono":"Activity","nodos":["No DHP","Antiarrítmicos I"]},{"titulo":"Metabólicos","icono":"Pill","nodos":["Glitazonas","Saxagliptina"]},{"titulo":"Gestión","icono":"LineChart","nodos":["Costo","Acceso","Beneficio"]}]},"proceso":{"titulo":"Revisión de seguridad","intro":"","pasos":[{"titulo":"Listar","detalle":"Medicación y venta libre.","icono":"ClipboardList","evidencia":"Lista."},{"titulo":"Identificar","detalle":"Fármacos que empeoran.","icono":"AlertTriangle","evidencia":"Riesgos."},{"titulo":"Alternativa","detalle":"Opción más segura.","icono":"Pill","evidencia":"Propuesta."},{"titulo":"Comunicar","detalle":"Médico y paciente.","icono":"Users","evidencia":"Nota."},{"titulo":"Seguir","detalle":"Síntomas y peso.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"AINE en IC estable","contexto":"Paciente con IC estable que inicia ibuprofeno y presenta edema y disnea.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Mantener el AINE.","correcta":false,"retro":"Puede descompensar la IC."},{"texto":"Suspender y buscar alternativa.","correcta":true,"retro":"La seguridad es prioritaria."},{"texto":"Aumentar el diurético solamente.","correcta":false,"retro":"No corrige la causa."}]}}$j$::jsonb;
