  -- 08. Nitratos: farmacocinética, tolerancia e interacciones
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El nitrato que dejó de funcionar","texto":"Un paciente usa nitroglicerina varias veces al día y nota que cada vez le dura menos. La tolerancia a los nitratos aparece con el uso continuo. El intervalo libre de nitratos es parte de la prescripción."},"objetivos":["Aplicar el uso de nitratos.","Explicar la tolerancia.","Reconocer la interacción con PDE-5.","Educar sobre el uso sublingual."],"conceptos":[{"icono":"Zap","termino":"Nitrato","definicion":"Vasodilatador que reduce la precarga."},{"icono":"Timer","termino":"Tolerancia","definicion":"Pérdida de efecto con uso continuo."},{"icono":"AlertTriangle","termino":"PDE-5","definicion":"Contraindicación con sildenafilo."},{"icono":"Pill","termino":"Sublingual","definicion":"Uso en la crisis de angina."}],"secciones":[{"titulo":"Uso clínico","parrafos":["La nitroglicerina sublingual alivia la angina en minutos. Se usa al inicio del dolor y se repite según indicación, con un máximo de tres dosis en 15 minutos; si no mejora, debe buscarse atención urgente. Los nitratos de acción prolongada, como el dinitrato de isosorbide o el mononitrato, se usan para prevención.","Los nitratos reducen la precarga y la demanda de oxígeno. Producen cefalea, rubor, hipotensión y taquicardia refleja. No se usan en hipotensión, infarto del ventrículo derecho ni estenosis aórtica grave."]},{"titulo":"Tolerancia","parrafos":["El uso continuo produce tolerancia, por lo que se requiere un intervalo libre de nitratos de 10-12 horas. El mononitrato se dosifica por la mañana y se deja la noche libre. El parche de nitroglicerina se retira por la noche.","El paciente debe entender el horario y no usar el nitrato de forma continua. La cefalea inicial suele mejorar, pero no debe tratarse aumentando la dosis."]},{"titulo":"Interacciones","parrafos":["Los inhibidores de la fosfodiesterasa 5, como sildenafilo y tadalafilo, están contraindicados con nitratos por riesgo de hipotensión grave. Se debe preguntar por su uso, incluso recreativo. También se revisan otros vasodilatadores y la presión basal.","El QF educa sobre la crisis, el almacenamiento y la caducidad. La nitroglicerina es volátil y debe conservarse en su frasco original. La revisión de la técnica y del plan de acción es parte de la dispensación."]}],"errores":[{"error":"Usar nitratos sin intervalo libre.","correccion":"Aparece tolerancia."},{"error":"Combinar con PDE-5.","correccion":"Hipotensión grave."},{"error":"No revisar la conservación.","correccion":"El fármaco pierde efecto."}],"comprueba":[{"pregunta":"¿Qué intervalo libre se recomienda?","respuesta":"10-12 horas."},{"pregunta":"¿Con qué fármacos se contraindican?","respuesta":"Inhibidores de PDE-5."},{"pregunta":"¿Cuántas dosis sublinguales antes de urgencias?","respuesta":"Tres en 15 minutos."}],"resumen":["Los nitratos alivian la angina.","La tolerancia exige intervalo libre.","La combinación con PDE-5 es peligrosa.","La educación cubre técnica y conservación."],"referencias":[{"cita":"European Society of Cardiology. 2024 ESC Guidelines for the management of chronic coronary syndromes. Eur Heart J. 2024.","url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/chronic-coronary-syndromes/"}],"imagenes":[{"ubicacion":"Nitratos","descripcion":"Uso sublingual, tolerancia e interacción con PDE-5.","alt":"Nitratos en la angina"}],"keywords":["nitratos angina","nitroglicerina","tolerancia nitratos","sildenafilo nitratos"],"mapa":{"centro":"Nitratos","ramas":[{"titulo":"Acción corta","icono":"Zap","nodos":["Nitroglicerina","Sublingual","Crisis"]},{"titulo":"Acción larga","icono":"Timer","nodos":["ISDN","ISMN","Mantenimiento"]},{"titulo":"Tolerancia","icono":"Repeat","nodos":["Intervalo 10-12 h","Horario"]},{"titulo":"Interacción","icono":"AlertTriangle","nodos":["Sildenafilo","Tadalafilo","Hipotensión"]}]},"proceso":{"titulo":"Checklist de nitratos","intro":"","pasos":[{"titulo":"Indicación","detalle":"Crisis o prevención.","icono":"Target","evidencia":"Diagnóstico."},{"titulo":"Horario","detalle":"Intervalo libre.","icono":"Timer","evidencia":"Esquema."},{"titulo":"Interacción","detalle":"PDE-5 y otros.","icono":"AlertTriangle","evidencia":"Entrevista."},{"titulo":"Técnica","detalle":"Sublingual y conservación.","icono":"GraduationCap","evidencia":"Demostración."},{"titulo":"Seguir","detalle":"Crisis y tolerancia.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Nitrato y sildenafilo","contexto":"Paciente con angina que usa sildenafilo y planea tomar nitroglicerina sublingual.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Permitir la combinación.","correcta":false,"retro":"Riesgo de hipotensión grave."},{"texto":"Advertir la contraindicación y contactar al médico.","correcta":true,"retro":"Debe evitarse la combinación."},{"texto":"Duplicar el nitrato.","correcta":false,"retro":"Aumenta el riesgo."}]}}$j$::jsonb;
