  -- 09. Betabloqueadores, calcioantagonistas y ranolazina en la angina crónica
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La angina que necesita segunda línea","texto":"Un paciente con angina sigue sintomático pese a betabloqueador y nitrato. La ranolazina es una opción de segunda línea, pero prolonga el QT y tiene interacciones. Elegir exige conocer el perfil."},"objetivos":["Aplicar la primera línea antianginosa.","Reconocer el lugar de la ranolazina.","Revisar interacciones y QT.","Individualizar según comorbilidad."],"conceptos":[{"icono":"Activity","termino":"Beta","definicion":"Reduce demanda de oxígeno."},{"icono":"Gauge","termino":"No DHP","definicion":"Reduce frecuencia y contractilidad."},{"icono":"Pill","termino":"Ranolazina","definicion":"Inhibe la corriente tardía de sodio."},{"icono":"AlertTriangle","termino":"QT","definicion":"Riesgo de proarritmia."}],"secciones":[{"titulo":"Primera línea","parrafos":["Los betabloqueadores y los calcioantagonistas son la primera línea para reducir la demanda de oxígeno. Los betabloqueadores son útiles en postinfarto y disfunción ventricular; los calcioantagonistas no dihidropiridínicos son una alternativa cuando el beta no se tolera. Los nitratos de acción prolongada se añaden para el alivio sintomático.","La elección depende de la frecuencia, la presión, la función ventricular y las comorbilidades. En la angina vasoespástica se prefieren los calcioantagonistas."]},{"titulo":"Ranolazina","parrafos":["La ranolazina inhibe la corriente tardía de sodio y reduce la sobrecarga de calcio, sin afectar la frecuencia ni la presión. Se usa como segunda línea en angina crónica refractaria. Puede prolongar el QT y debe evitarse en pacientes con QT largo, bradicardia grave o insuficiencia hepática.","Es sustrato del CYP3A4 y se contraindica con inhibidores potentes como ketoconazol, itraconazol, claritromicina y ritonavir. También interactúa con simvastatina y otros fármacos. El QF revisa el ECG y la medicación completa."]},{"titulo":"Individualización","parrafos":["La angina crónica requiere también control del riesgo: antiagregación, estatina de alta intensidad, control de la presión y del tabaco. La revascularización se considera según la anatomía y los síntomas. El tratamiento farmacológico no sustituye la evaluación del riesgo.","El QF revisa la adherencia, la técnica del nitrato sublingual y las interacciones. La educación sobre cuándo usar el rescate y cuándo consultar es parte del plan."]}],"errores":[{"error":"Usar ranolazina con QT largo.","correccion":"Riesgo de torsade."},{"error":"Combinar beta con no DHP.","correccion":"Bradicardia y bloqueo."},{"error":"Olvidar la estatina y el antiagregante.","correccion":"El riesgo de eventos persiste."}],"comprueba":[{"pregunta":"¿Cuál es la primera línea?","respuesta":"Betabloqueador o calcioantagonista."},{"pregunta":"¿Qué hace la ranolazina?","respuesta":"Inhibe la corriente tardía de sodio."},{"pregunta":"¿Qué se revisa antes de usarla?","respuesta":"QT e interacciones del CYP3A4."}],"resumen":["La primera línea reduce la demanda.","La ranolazina es de segunda línea.","El QT y el CYP3A4 limitan su uso.","El riesgo cardiovascular se trata siempre."],"referencias":[{"cita":"European Society of Cardiology. 2024 ESC Guidelines for the management of chronic coronary syndromes. Eur Heart J. 2024.","url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/chronic-coronary-syndromes/"},{"cita":"SESCAM. Ranolazina: hoja de evaluación de medicamentos. Castilla-La Mancha; 2011.","url":"https://sanidad.castillalamancha.es/sites/sescam.castillalamancha.es/files/documentos/farmacia/ranolazina.pdf"}],"imagenes":[{"ubicacion":"Angina","descripcion":"Primera y segunda línea antianginosa.","alt":"Betabloqueadores, calcioantagonistas y ranolazina"}],"keywords":["angina crónica","ranolazina","betabloqueador angina","calcioantagonista angina"],"mapa":{"centro":"Angina crónica","ramas":[{"titulo":"Primera línea","icono":"Activity","nodos":["Beta","Calcio","Nitrato"]},{"titulo":"Segunda línea","icono":"Pill","nodos":["Ranolazina","Ivabradina","Nicorandil"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["QT","CYP3A4","Bradicardia"]},{"titulo":"Riesgo","icono":"ShieldCheck","nodos":["Estatina","Antiagregante","Revascularizar"]}]},"proceso":{"titulo":"Elegir antianginoso","intro":"","pasos":[{"titulo":"Evaluar","detalle":"Frecuencia, presión y FEVI.","icono":"ClipboardList","evidencia":"Ficha."},{"titulo":"Primera línea","detalle":"Beta o calcio.","icono":"Activity","evidencia":"Fórmula."},{"titulo":"Añadir","detalle":"Nitrato o segunda línea.","icono":"Pill","evidencia":"Esquema."},{"titulo":"Revisar","detalle":"QT y CYP3A4.","icono":"AlertTriangle","evidencia":"ECG."},{"titulo":"Seguir","detalle":"Síntomas y adherencia.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Angina refractaria","contexto":"Paciente con angina a pesar de betabloqueador y nitrato, sin QT largo ni insuficiencia hepática.","pregunta":"¿Qué segunda línea se valora?","opciones":[{"texto":"Ranolazina.","correcta":true,"retro":"Es una opción de segunda línea."},{"texto":"Duplicar el nitrato sin intervalo.","correcta":false,"retro":"Aumenta la tolerancia."},{"texto":"Combinar beta con verapamilo.","correcta":false,"retro":"Riesgo de bradicardia."}]}}$j$::jsonb;
