  -- 10. Caso: ICFEr tras hospitalización – transición a ARNI y vigilancia de potasio
  v_data := $j${"v":1,"duracion":30,"gancho":{"titulo":"El alta es el inicio de la titulación","texto":"Un hombre de 58 años egresa tras una descompensación con FEVI de 30 %. El alta no termina el tratamiento: empieza la transición a ARNI, la vigilancia del potasio y la titulación de los cuatro pilares. El QF coordina ese proceso."},"objetivos":["Aplicar la transición IECA-ARNI.","Vigilar potasio y función renal.","Titular los pilares.","Educar al paciente al alta."],"conceptos":[{"icono":"Timer","termino":"36 horas","definicion":"Lavado entre IECA y ARNI."},{"icono":"TestTube","termino":"Potasio","definicion":"Riesgo con ARM y SRAA."},{"icono":"Layers","termino":"Titulación","definicion":"Escalar a dosis objetivo."},{"icono":"Users","termino":"Autocuidado","definicion":"Peso, sal y signos de alarma."}],"secciones":[{"titulo":"Transición","parrafos":["El paciente egresa con enalapril, carvedilol a dosis baja, espironolactona, furosemida y dapagliflozina. El cardiólogo planea cambiar el enalapril por sacubitrilo/valsartán. El QF asegura que se suspenda el IECA y se espere al menos 36 horas antes de iniciar el ARNI para evitar angioedema.","La transición se registra y se educa: no se toman ambos, y se consulta si aparece hinchazón de labios, lengua o dificultad para respirar. La dosis inicial de ARNI es 24/26 mg cada 12 horas, con titulación posterior."]},{"titulo":"Potasio y función renal","parrafos":["El potasio de 4,9 y la creatinina de 1,3 obligan a control semanal al inicio y después de cada ajuste. El paciente no debe usar suplementos de potasio ni sales de reemplazo sin indicación. Se revisan AINE, trimetoprim y otros fármacos que retienen potasio.","La caída leve de la TFG puede ser esperada. Un aumento significativo de creatinina o una hiperpotasemia persistente exigen revisión del esquema y coordinación con el médico."]},{"titulo":"Titulación y educación","parrafos":["Se titulan carvedilol, espironolactona y ARNI según presión, frecuencia, potasio y síntomas. La dapagliflozina se mantiene. El paciente registra el peso diario, reduce la sal y conoce los signos de alarma: disnea, edema, ganancia de peso, mareo o palpitaciones.","El seguimiento temprano en la primera semana y luego cada dos a cuatro semanas permite ajustar sin perder continuidad. El caso muestra que la transición al alta es una intervención farmacéutica compleja y de alto impacto."]}],"errores":[{"error":"No esperar 36 horas.","correccion":"Riesgo de angioedema."},{"error":"No controlar potasio.","correccion":"Riesgo de hiperpotasemia."},{"error":"No educar sobre peso.","correccion":"Se pierde la detección temprana."}],"comprueba":[{"pregunta":"¿Cuánto esperar antes del ARNI?","respuesta":"Al menos 36 horas."},{"pregunta":"¿Qué se controla al inicio?","respuesta":"Potasio y creatinina."},{"pregunta":"¿Qué se titula?","respuesta":"ARNI, beta y ARM."}],"resumen":["El alta inicia la titulación.","La transición a ARNI exige 36 horas.","El potasio y la función renal guían el ajuste.","La educación sostiene el autocuidado."],"referencias":[{"cita":"European Society of Cardiology. 2026 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2026.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Heart-Failure"},{"cita":"AEMPS-CIMA. Ficha técnica de Entresto 24 mg/26 mg comprimidos recubiertos con película.","url":"https://cima.aemps.es/cima/dochtml/ft/1151058001/FT_1151058001.html"}],"imagenes":[{"ubicacion":"Caso","descripcion":"Transición IECA-ARNI con controles de potasio.","alt":"Caso de ICFEr tras hospitalización"}],"keywords":["transición arni","icfer alta","potasio insuficiencia cardíaca","titulación ic"],"mapa":{"centro":"Transición al alta","ramas":[{"titulo":"IECA-ARNI","icono":"Timer","nodos":["Suspender","36 h","Iniciar"]},{"titulo":"Potasio","icono":"TestTube","nodos":["4,9","Control semanal","Ajuste"]},{"titulo":"Pilares","icono":"Layers","nodos":["Beta","ARM","iSGLT2"]},{"titulo":"Educación","icono":"Users","nodos":["Peso","Sal","Alarma"]}]},"proceso":{"titulo":"Seguimiento al alta","intro":"","pasos":[{"titulo":"Conciliar","detalle":"Medicación previa y nueva.","icono":"Repeat","evidencia":"Lista."},{"titulo":"Transición","detalle":"36 horas antes del ARNI.","icono":"Timer","evidencia":"Registro."},{"titulo":"Controlar","detalle":"Potasio y creatinina.","icono":"TestTube","evidencia":"Laboratorio."},{"titulo":"Titular","detalle":"Pilares a dosis objetivo.","icono":"Layers","evidencia":"Esquema."},{"titulo":"Educar","detalle":"Peso, sal y alarma.","icono":"Users","evidencia":"Consejería."}]},"caso":{"titulo":"Enalapril a ARNI","contexto":"Paciente con ICFEr que toma enalapril y cambiará a sacubitrilo/valsartán; potasio 4,9 y creatinina 1,3.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Iniciar ambos el mismo día.","correcta":false,"retro":"Riesgo de angioedema."},{"texto":"Suspender IECA, esperar 36 horas e iniciar ARNI.","correcta":true,"retro":"Transición segura."},{"texto":"Suspender el ARM.","correcta":false,"retro":"Se pierde un pilar."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Caso: ICFEr tras hospitalización – transición a ARNI y vigilancia de potasio$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Caso: ICFEr tras hospitalización – transición a ARNI y vigilancia de potasio$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  IF v_n > 0 THEN
    INSERT INTO aula_republicaciones_aprobadas (course_id, aprobado_por, nota)
    SELECT v_curso, 'Dirección académica de Edvanta', 'Clases ampliadas con experiencia interactiva (144_experiencias_farmacologia_cardiovascular_2.sql).'
     WHERE EXISTS (SELECT 1 FROM aula_courses WHERE id = v_curso AND current_version_id IS NOT NULL);
  END IF;

  RAISE NOTICE 'Experiencias de %: % clases.', $t$Curso de Farmacología Cardiovascular$t$, v_n;
END $exp$;
